def featurise(obs):
    GRID = 128.0
    x_n = obs[0] / GRID - 0.5
    y_n = obs[1] / GRID - 0.5
    vx, vy = obs[2], obs[3]
    wx, wy = obs[4], obs[5]
    w_norm = np.sqrt(wx**2 + wy**2) + 1e-8
    wx_u, wy_u = wx / w_norm, wy / w_norm
    w_log = np.log1p(w_norm) / 4.0
    gx, gy = 64.0, 127.0
    dx, dy = (gx - obs[0]) / GRID, (gy - obs[1]) / GRID
    dist = np.sqrt(dx**2 + dy**2) + 1e-8
    dx_u, dy_u = dx / dist, dy / dist
    dist_n = dist
    dot_goal_wind = dx_u * wx_u + dy_u * wy_u
    feat = np.array([
        x_n, y_n, vx, vy,
        wx_u, wy_u, w_log,
        dx_u, dy_u, dist_n,
        dot_goal_wind,
    ], dtype=np.float32)
    return feat


